"""
黄大仙灵签 100 签解读库（解曰 / 典故 / 运势解析）
=================================================
签诗正文与吉凶以《data/lingqian100.json》（啬色园官方数据集）为准，
本文件为配套的传统解签释义，依据签诗意象、典故与五等吉凶编写。
字段：
  jie     解曰（签文释义，2-4句）
  diangu  典故（古人占验故事，1-3句）
  yunshi  运势解析（整体运势一句话 + 事业/财运/感情/健康分项）
"""
from __future__ import annotations

# {签号: {"jie": ..., "diangu": ..., "yunshi": ...}}
NOTES: dict = {
1: {"jie": "此签大吉，如姜公遇文王，时来运转、风云际会。所谋顺遂，贵人扶持，多年心愿可望一朝达成。", "diangu": "姜子牙渭水垂钓，遇周文王访贤，辅佐武王伐纣灭商，受封于齐，功成名就。", "yunshi": "整体：时运亨通，大有可为。事业：如鱼得水，大展宏图。财运：财源广进，置业有成。感情：良缘天定，喜讯可期。健康：精神饱满，百病不侵。"},
2: {"jie": "枯木逢春，柳暗花明。前路虽有迷惘，然机缘巧合自得佳境，凡事转机在望，宜顺势而为，勿失良机。", "diangu": "相传王道真（渔人）偶入桃源仙境，见洞天福地，归来已更年岁，喻意外之遇。", "yunshi": "整体：否极泰来，渐入佳境。事业：旧业重振，机遇初现。财运：财路渐开，不可冒进。感情：旧缘复燃，和好如初。健康：体气渐复，调养为要。"},
3: {"jie": "美材虽在，惜乎斧工失当。喻才德虽具而未得其用，须反省方法、谨慎行事，方能成器。", "diangu": "鲁班（公输般）伐木取材，以规矩绳墨制器，喻技艺须合规矩方能成材。", "yunshi": "整体：怀才未遇，宜自省。事业：暂处蛰伏，静待时机。财运：进账平平，量入为出。感情：聚少离多，多加沟通。健康：小恙反复，注意作息。"},
4: {"jie": "雏燕学飞，上下盘旋，终能振翅高飞。喻循序渐进、功夫自成，家宅安宁，子女有成。", "diangu": "紫燕衔泥筑巢，教雏学飞，呢喃檐前，一片生机。", "yunshi": "整体：渐入佳境，稳中有进。事业：稳扎稳打，水到渠成。财运：小财可积，细水长流。感情：两情相悦，家庭和睦。健康：身心安泰。"},
5: {"jie": "昨夜狂风，百花倾折，幸有惜花之人早起培根。喻虽有波折终得挽救，凡事宜早作准备，根固则叶茂。", "diangu": "陶渊明惜花爱菊，狂风摧花后培土护根，使花木复生。", "yunshi": "整体：有惊无险，失而复得。事业：虽有挫折，努力可挽。财运：失而复得，守成为上。感情：风波过后，重归于好。健康：早防早治，并无大碍。"},
6: {"jie": "一帆万里，故友重逢，诗酒风流，其乐陶陶。喻人际和睦、贵人来助，诸事顺遂。", "diangu": "苏东坡与胜友同游滕王阁，谈风论月，畅叙幽情，极尽雅兴。", "yunshi": "整体：人和事顺，喜乐安康。事业：同侪相助，合作有成。财运：正财顺遂，偏财亦有。感情：良朋益友，姻缘和乐。健康：气机顺畅。"},
7: {"jie": "秋雁南归，红叶满庭，景物虽美而带离思。喻时令流转、人事有聚散，宜随遇而安，守常待时。", "diangu": "薛丁山秋日射雁，雁阵南飞，红叶纷飞，触动思归之情。", "yunshi": "整体：平平淡淡，宜守常。事业：进展迟缓，宜养精蓄锐。财运：平稳而已，勿贪勿急。感情：聚少离多，思念为伴。健康：注意寒暖，预防风寒。"},
8: {"jie": "鹊巢鸠占，宾主失位。喻有争夺之象，或遇小人侵占、是非纠缠，凡事退让三分，切勿强争。", "diangu": "斑鸠强占喜鹊之巢，宾主错位，喻他人夺我之位、占我之利。", "yunshi": "整体：谨防是非小人。事业：防小人夺功，慎防口舌。财运：谨防破财，勿信他人。感情：防第三者介入，宜守正。健康：心绪不宁，郁结为病。"},
9: {"jie": "琴韵悠扬，嘉宾咸集，对菊飞觞。喻心境恬淡而福自至，人缘极佳，诸事如意。", "diangu": "陶渊明辞官归隐，东篱采菊，宴集雅士，抚琴吟咏，乐在其中。", "yunshi": "整体：恬淡自得，福气自来。事业：名成利就，口碑载道。财运：收益颇丰，财来有道。感情：良缘和美，琴瑟和鸣。健康：安然无恙，宜养情志。"},
10: {"jie": "明月当空，偶被云遮。喻一时困顿、才志未展，然云开月现有时，宜坚心忍性，静待时机。", "diangu": "苏秦游说诸侯初遭冷遇，归家受辱，后发奋悬梁刺股，终佩六国相印。", "yunshi": "整体：一时困顿，终有出头。事业：暂处低谷，蓄势待发。财运：财气未聚，宜节流。感情：缘分未至，不必强求。健康：情绪低落，宜自开解。"},
11: {"jie": "杨柳垂堤，紫燕穿梭，风光和畅。喻时运亨通、人缘和谐，诸事顺意，宜把握良机。", "diangu": "汉文帝于御苑赏柳，柳丝如烟、燕舞翩翩，君臣同乐。", "yunshi": "整体：顺风顺水，诸事如意。事业：步步高升，人缘助力。财运：财源兴旺。感情：姻缘和美，琴瑟和谐。健康：身心安康。"},
12: {"jie": "海市蜃楼，幻象无边，转瞬散灭。喻所求皆虚、所谋皆空，须脚踏实地，勿存侥幸之心。", "diangu": "李白醉后见水中月影，入水捞月而不得，喻虚妄难求。", "yunshi": "整体：虚多实少，脚踏实地。事业：镜花水月，难有实果。财运：谨防虚耗，勿投机。感情：虚情假意，勿轻信。健康：心神恍惚，注意调养。"},
13: {"jie": "岭梅初放，晶莹入杯，早梅占魁。喻寒中见春、苦尽甘来，惟须及早行动，方能占先。", "diangu": "孟浩然踏雪寻梅，见岭南寒梅初放，晶滢入杯，早春报信。", "yunshi": "整体：先苦后甜，早动为宜。事业：抢占先机，勿再迟疑。财运：略有进益。感情：良缘需主动争取。健康：注意保暖，防寒侵。"},
14: {"jie": "种竹听雨，醉卧花边，闲适自得。喻宜安守本分、淡泊自持，知足常乐，不强求则无咎。", "diangu": "苏东坡幽居种竹，买春赏雨，醉卧杏花丛边，诗酒自娱。", "yunshi": "整体：安贫乐道，知足常乐。事业：宜守成不宜扩张。财运：平淡，节用为要。感情：安于现状，平淡是真。健康：安闲则健。"},
15: {"jie": "仙槎泛月，蟾宫任游。喻登高望远、心想事成，名利双收，所谋皆遂。", "diangu": "唐明皇梦游月宫，闻霓裳羽衣之曲，得睹天上仙境。", "yunshi": "整体：大吉之兆，心想事成。事业：青云直上，贵人扶持。财运：财帛丰盈。感情：良缘美满。健康：神清气爽。"},
16: {"jie": "夕阳西下，牧童归家，笛声悠扬。喻劳而有获、归得其安，家宅平安，进退有度。", "diangu": "牧童跨牛晚归，短笛横吹，暮色中一片恬然和乐。", "yunshi": "整体：劳有所得，平安是福。事业：收成正果，功成身退。财运：平稳小丰。感情：家庭和乐。健康：安健。"},
17: {"jie": "秋水蒹葭，月色满庭。喻求贤若渴、遇合有时，凡事耐心寻访，自得贤助。", "diangu": "萧何月下追韩信，慧眼识才，终助刘邦成就帝业。", "yunshi": "整体：得遇贵人，如虎添翼。事业：求才得助，如鱼得水。财运：财随人聚。感情：良缘需主动寻觅。健康：身心佳。"},
18: {"jie": "杜鹃啼血，客心悲切。喻愁绪满怀、思乡念亲，处境孤寂，宜自宽慰，早谋归计。", "diangu": "望帝魂化杜鹃，啼血哀鸣；客居异乡者闻之，倍思故园。", "yunshi": "整体：愁云笼罩，宜自宽怀。事业：阻滞难伸，暂守为要。财运：有损，守稳。感情：相思成愁，两地分离。健康：郁结伤神，宜宽怀。"},
19: {"jie": "乾卦三连，潜龙勿用。喻宜潜藏修养、参透玄机，循序渐进，则百福骈臻。", "diangu": "伏羲仰观俯察，画八卦以通神明之德，类万物之情。", "yunshi": "整体：厚积薄发，先潜后进。事业：蓄势待机，勿轻举妄动。财运：蓄财待机。感情：静待缘至。健康：养精蓄锐。"},
20: {"jie": "天上仙花，人间难种。喻所愿虽美、机缘难得，凡事当量力而行，顺天应命。", "diangu": "借天上仙花难植人间之喻，言凡尘福缘各有定数，强求不得。", "yunshi": "整体：量力而行，莫好高骛远。事业：脚踏实地则成。财运：平稳无波。感情：缘分尚浅，勿强求。健康：注意养生。"},
21: {"jie": "红霞抹锦，桃杏争妍。喻春色满园、气象一新，好事当头，惟须权衡取舍，择优而从。", "diangu": "武则天于冬月诏令百花齐放，桃杏竞艳，独牡丹不屈被贬洛阳。", "yunshi": "整体：春意盎然，择优而行。事业：才华为众所赏。财运：财气旺。感情：桃花颇旺，宜慎择。健康：佳。"},
22: {"jie": "秋水伊人，天南地北。喻相思阻隔、两地悬望，凡事难得圆满，须防情扰心乱。", "diangu": "陈妙常与潘必正两情相悦而遭阻隔，愁思难遣。", "yunshi": "整体：阻隔难通，静守待时。事业：进展受阻。财运：欠佳，宜守。感情：分离之象，甚为挂牵。健康：愁思伤身，宜开解。"},
23: {"jie": "邯郸一梦，富贵如烟。喻荣华虚妄、莫过分执着，醒时方知平淡是福。", "diangu": "卢生邯郸客店遇吕翁，黄粱一梦历尽荣华，梦醒黄粱未熟。", "yunshi": "整体：浮华如梦，莫执迷。事业：虚名无实，宜务实。财运：浮财难守。感情：梦中情缘，终归平淡。健康：宜节劳养神。"},
24: {"jie": "诗酒琴棋，聊解愁怀，然座中无客，终难尽兴。喻英雄失路、知音难觅，宜耐守时艰。", "diangu": "秦琼落难潞州，当锏卖马，英雄失路，壮志难酬。", "yunshi": "整体：困顿之际，耐守为要。事业：暂处困境，不宜张扬。财运：拮据，宜省用。感情：知音难求。健康：郁结于心，宜排解。"},
25: {"jie": "群山朝岳，众星拱北。喻威望日隆、众望所归，功名事业皆登高峰。", "diangu": "明太祖朱元璋登基，天下归心，如群山朝拱中岳。", "yunshi": "整体：众望所归，大吉大利。事业：登峰造极，威望日盛。财运：大旺。感情：正缘显达。健康：体魄强壮。"},
26: {"jie": "花影月镜，鹤唳催归。喻身在他乡、闻声思归，凡事不宜久恋，早作归计为佳。", "diangu": "徐庶被赚归曹，临别荐贤，身去心留，思归故里。", "yunshi": "整体：归心似箭，宜收宜守。事业：宜收不宜放。财运：见好即收。感情：远隔之缘，聚少离多。健康：思虑伤神。"},
27: {"jie": "粉蝶晒翅，蚁阵有序，动合天时。喻凡事当审时度势、进退有节，自然顺遂。", "diangu": "晴日粉蝶晒翅、蚁阵迁排，万物知时，动而有节。", "yunshi": "整体：顺时而动，进退有度。事业：按部就班即顺。财运：小有收获。感情：循序渐进。健康：顺应节律则安。"},
28: {"jie": "浔阳月夜，琵琶声咽，两处相思。喻沦落之感、别离之愁，凡事多阻，宜安分守己。", "diangu": "白居易贬官浔阳，江头夜闻琵琶，青衫尽湿，感怀身世。", "yunshi": "整体：时运多阻，安守为上。事业：流离多阻，宜守职。财运：有失，节流。感情：离愁别恨，两地挂念。健康：忧思成疾，宜宽心。"},
29: {"jie": "鲈脍菊酒，晚凉泛棹，悠然自得。喻得尝所愿、归得其乐，知进退者自享清福。", "diangu": "张翰见秋风起，思吴中莼羹鲈脍，遂辞官归乡，纵情山水。", "yunshi": "整体：急流勇退，自得其乐。事业：急流勇退亦佳。财运：丰足。感情：家庭温馨。健康：安泰。"},
30: {"jie": "倾国倾城，红颜薄命，马嵬遗恨。喻繁华易逝、乐极生悲，凡事莫贪欢纵欲。", "diangu": "安史之乱，唐明皇仓皇出逃，至马嵬坡赐死杨贵妃，长恨绵绵。", "yunshi": "整体：乐极生悲，宜防盛衰。事业：防盛极而衰。财运：有破耗。感情：红颜薄命之叹，防情劫。健康：宜节欲养身。"},
31: {"jie": "狂风骤雨，溪花尽落，渔舟失向。喻前程多险、风波骤起，凡事谨慎，宜守不宜进。", "diangu": "渔翁梦中遇狂风骤雨，溪畔桃花零落，持篙撑船迷失东西。", "yunshi": "整体：风波骤起，以守为安。事业：暂时停步，规避风险。财运：谨防损失。感情：波澜起伏。健康：慎防意外。"},
32: {"jie": "十九年苦，餐毛嚼雪，惟羊作伴。喻困顿已久、孤苦无依，然守节不移，终有归期。", "diangu": "苏武奉命出使匈奴，被扣北海牧羊十九年，持节不屈。", "yunshi": "整体：苦守终有出头日。事业：苦熬待转，坚守本心。财运：清苦渐兴。感情：孤守中见真情。健康：体弱，宜加珍摄。"},
33: {"jie": "曹虽有谋，难瞒诸葛。喻小人算计终有破绽，但亦须防患未然，谨慎为上。", "diangu": "曹操多谋，然其计屡被诸葛亮识破，如借东风、木牛流马皆被看穿。", "yunshi": "整体：智高一筹，谨慎为胜。事业：谋事在人，多思则成。财运：防诈防骗。感情：慧眼识人。健康：无碍。"},
34: {"jie": "大舜耕山，孝德感天，善恶分明。喻以德服人、勤勉自持，家道昌隆。", "diangu": "舜耕于历山，以孝德感化顽劣父母兄弟，终受禅为帝。", "yunshi": "整体：以德服人，善有善报。事业：德行为先，自有回报。财运：稳步渐增。感情：贤良和顺。健康：康健。"},
35: {"jie": "天降大任，先劳筋骨。喻先难后易，历尽艰辛方成正果，切勿半途而废。", "diangu": "唐僧玄奘西行取经，历经九九八十一难，终得真经。", "yunshi": "整体：先难后易，坚持必胜。事业：劳而有功，勿轻言弃。财运：先苦后甜。感情：经得考验方见真情。健康：注意劳逸结合。"},
36: {"jie": "船到岸、人归村，风雨已过，前程在望。喻困厄将解、归期在即，诸事渐入顺境。", "diangu": "薛平贵困守寒窑多年，终得归家与王宝钏团聚，苦尽甘来。", "yunshi": "整体：否极泰来，归期在望。事业：渐入顺境。财运：将见起色。感情：破镜重圆。健康：渐复。"},
37: {"jie": "月夜秋江，钓鳌得鱼，与友飞觞。喻雅兴高致、所得称心，贵人同乐，诸事如意。", "diangu": "苏东坡月夜泛舟赤壁，垂钓秋江，与客飞觞赋诗，乐而忘返。", "yunshi": "整体：称心如意，乐在其中。事业：志得意满，宾朋相佐。财运：称心如意。感情：知己相伴。健康：畅适。"},
38: {"jie": "归去来兮，室堪容膝，倚杖看山。喻退一步海阔天空，安贫乐道自有真趣。", "diangu": "陶渊明不愿为五斗米折腰，挂印归田，采菊东篱，悠然自得。", "yunshi": "整体：急流知退，另辟天地。事业：急流知退，随性而为。财运：俭朴自足。感情：恬淡相守。健康：颐养天年。"},
39: {"jie": "耻食周粟，饿死首阳。喻守节不移、清高自许，名垂千古，然亦示人不可过执。", "diangu": "伯夷叔齐耻食周粟，隐于首阳山采薇而食，终饿死山中。", "yunshi": "整体：守节清名，宜知变通。事业：守节自持，不求富贵。财运：清贫自守。感情：重义轻利。健康：自苦则伤，宜变通。"},
40: {"jie": "知音已逝，碎琴相酬。喻知音难觅、缘尽情断，凡事不可强求，各安天命。", "diangu": "俞伯牙痛失知音钟子期，碎琴绝弦，终身不复鼓琴。", "yunshi": "整体：知音难觅，随缘自安。事业：独木难支，宜广结缘。财运：有失，守稳。感情：情断缘尽，宜放下。健康：悲戚伤身，宜开怀。"},
41: {"jie": "浮槎到天河，曾见天姬织锦。喻机缘奇遇、见所未见，凡事有意想不到之喜。", "diangu": "张骞乘浮槎泛至天河，得见织女织锦，获支机石而归。", "yunshi": "整体：奇遇良机，喜出望外。事业：机缘巧合，另辟蹊径。财运：意外之财。感情：天赐奇缘。健康：佳。"},
42: {"jie": "月下花栏，美人定国。喻以柔克刚、智取为上，大事可成，惟须谨慎周详。", "diangu": "王允设连环计，以貂蝉离间董卓吕布，终除奸贼。", "yunshi": "整体：智谋取胜，谨慎为先。事业：谋略得当，成功在望。财运：智取可得。感情：美人关前，防沉迷。健康：佳。"},
43: {"jie": "直谏获罪，雪拥蓝关。喻直言招尤、时运不济，宜谨言慎行，忍耐待时。", "diangu": "韩愈谏迎佛骨触怒宪宗，被贬潮州，途遇大雪，马困蓝关。", "yunshi": "整体：直言贾祸，收敛为要。事业：言语谨慎，低调行事。财运：有损，宜守。感情：多口舌之争。健康：风寒之症，注意保暖。"},
44: {"jie": "满园春色，牡丹称王。喻才德出众、独占鳌头，然树大招风，宜谦和自处。", "diangu": "唐明皇于天宝年间评花，牡丹艳冠群芳，被尊为花王。", "yunshi": "整体：出类拔萃，谦和自处。事业：独占鳌头，功高防忌。财运：丰盈。感情：众星拱月，防自满。健康：佳。"},
45: {"jie": "观棋烂柯，世易时移。喻沉迷一事、岁月飞逝，宜把握光阴，莫负眼前。", "diangu": "王质入山伐樵，观二仙对弈，斧柯已烂，归时世上已过千年。", "yunshi": "整体：光阴易逝，及时奋起。事业：蹉跎岁月，宜奋起直追。财运：平平。感情：空耗时光，宜珍惜眼前。健康：注意作息规律。"},
46: {"jie": "黄柑献曹，剖之皆空。喻虚有其表、事有诈伪，防人欺瞒，凡事细察。", "diangu": "左慈献柑与曹操，剖视柑内皆空，戏弄于当世奸雄。", "yunshi": "整体：虚虚实实，细察为要。事业：谨防上当受骗。财运：防损财。感情：虚情假意，勿轻信。健康：防饮食不洁。"},
47: {"jie": "千里索荆州，刘备泪垂。喻所求难遂、徒费唇舌，凡事当寻善策，勿作无谓纠缠。", "diangu": "鲁肃奉吴主之命索还荆州，刘备流泪推搪，终无结果。", "yunshi": "整体：所求难遂，另谋良策。事业：进展受阻，需另辟蹊径。财运：欠佳，宜守。感情：牵缠难决，宜明断。健康：忧烦伤神。"},
48: {"jie": "绣阁听琴，夤夜私奔，当垆卖酒。喻为情所动、甘苦与共，惟亦示冲动之戒。", "diangu": "卓文君听琴慕相如，夤夜私奔，临邛当垆卖酒，甘苦与共。", "yunshi": "整体：为情所动，甘苦与共。事业：从头创业，苦中作乐。财运：清苦渐兴。感情：真情可嘉，惟须务实。健康：操劳，宜节。"},
49: {"jie": "十年苦读，题桥立志，终酬夙愿。喻立志坚定、勤学不辍，功名终成。", "diangu": "司马相如离蜀时题桥立誓，不乘高车驷马不过此桥，后终显达。", "yunshi": "整体：有志竟成，功不唐捐。事业：持之以恒，终成大器。财运：渐入佳境。感情：功成自有良缘。健康：宜劳逸相济。"},
50: {"jie": "潜奔难渡，幸逢渔父，赠剑不受。喻绝处逢生、义气相助，贵人暗助，感恩自存。", "diangu": "伍子胥逃难江边，渔父渡之过江，坚辞宝剑之赠，仗义相救。", "yunshi": "整体：逢凶化吉，贵人暗助。事业：危中得助，转危为安。财运：有贵人助。感情：患难见真情。健康：化险为夷。"},
51: {"jie": "剪桐为珪，戏言成真。喻一言既出、驷马难追，凡事慎始，言而有信。", "diangu": "周成王削桐叶为珪戏封叔虞，太史以“天子无戏言”谏，遂封于唐。", "yunshi": "整体：言出必行，慎言笃行。事业：承诺须兑现，信用为本。财运：守信则顺。感情：一言定情。健康：无恙。"},
52: {"jie": "清浊分判，天地乃成。喻是非分明、正邪立判，凡事循理而行，自见分晓。", "diangu": "盘古开天辟地，清者上升为天，浊者下沉为地，三才乃立。", "yunshi": "整体：是非分明，循理而行。事业：条理分明则成。财运：明明白白。感情：泾渭分明，真诚相待。健康：阴阳调和。"},
53: {"jie": "珠履三千，弹铗归来，英雄自荐。喻怀才之士终得赏识，主动争取，自有重用。", "diangu": "冯谖为孟尝君门下客，弹铗而歌求鱼求车，后为孟尝君市义，深得重用。", "yunshi": "整体：自荐得用，英雄有用武地。事业：毛遂自荐，得遇明主。财运：渐丰。感情：主动出击，方得良缘。健康：佳。"},
54: {"jie": "梦蝶栩栩，醒后茫然。喻真假难辨、得失莫执，顺其自然，不必强求。", "diangu": "庄周梦为蝴蝶，栩栩然自得其乐，醒后不知周之梦蝶还是蝶梦周。", "yunshi": "整体：虚实难料，顺其自然。事业：虚实难辨，宜务实。财运：浮浮沉沉。感情：如幻如真，随缘。健康：养神为要。"},
55: {"jie": "沉香遗恨，渡江忆贤。喻清廉自守、去留分明，虽失于形，得于心。", "diangu": "吴隐之清操自守，辞官渡江时投沉香于水，以明廉志。", "yunshi": "整体：清廉自守，虽失犹得。事业：守正自持，名节为重。财运：无妄之财勿取。感情：淡泊相守。健康：心平气和。"},
56: {"jie": "桃剑化龙，见水腾空。喻潜龙在渊、时机一至，飞腾万里，宜蓄势待发。", "diangu": "吕洞宾桃木剑炼化成龙，遇水腾空，飞升万里。", "yunshi": "整体：潜力无穷，待机而发。事业：厚积薄发，一鸣惊人。财运：后劲十足。感情：好事多磨。健康：佳。"},
57: {"jie": "春雨初歇，买花一枝，独得青睐。喻精诚所至、金石为开，惟须放低身段，耐心经营。", "diangu": "卖油郎秦重积攒多时，买花赠莘瑶琴，精诚所至，终得花魁芳心。", "yunshi": "整体：精诚所至，金石为开。事业：小处着手，终成大业。财运：聚沙成塔。感情：精诚所至，终成眷属。健康：佳。"},
58: {"jie": "谏而不听，崤山大败。喻忠言逆耳、刚愎自用则败，凡事多听劝诫，莫逞强。", "diangu": "蹇叔力谏秦穆公不可远袭郑国，不听，秦师果然大败于崤山。", "yunshi": "整体：忠言当听，切忌刚愎。事业：广纳谏言，防独断。财运：防大损。感情：多听人劝。健康：防意外。"},
59: {"jie": "效颦增丑，山鸡岂胜凤凰。喻邯郸学步、自不量力，宜扬己所长，勿盲目模仿。", "diangu": "东施效仿西施捧心蹙眉，反增其丑；吴王宠西施而国破，祸福自见。", "yunshi": "整体：量力而行，扬长避短。事业：勿盲目跟风。财运：忌投机。感情：强求不得，做自己。健康：自信则安。"},
60: {"jie": "醉笔和番，酒中见真才。喻怀才不露、机缘方显，惟嗜酒误事，宜自节制。", "diangu": "李白醉草吓蛮书，才惊四座；然日饮长安，酒中岁月。", "yunshi": "整体：才名终显，宜节酒性。事业：才名终显，机缘自来。财运：得而复失之虑。感情：随缘而安。健康：少饮为佳。"},
61: {"jie": "十二金牌，功败垂成。喻奸人作祟、功亏一篑，凡事防小人所阻，审慎自保。", "diangu": "岳飞北伐连捷，秦桧矫诏发十二道金牌召其班师，功败垂成。", "yunshi": "整体：防小人作祟，功败垂成。事业：防小人所阻，谨守成果。财运：有失。感情：防离间。健康：防暗疾。"},
62: {"jie": "美玉韫匮，待价而沽。喻才德宜藏，待时而动，不可自贬身价，急求则失。", "diangu": "孔子以美玉韫椟而藏自喻，待善价而沽，不枉己求售。", "yunshi": "整体：蓄势待价，静待良机。事业：养望待时，勿自贬。财运：静待良机。感情：宁缺毋滥。健康：安。"},
63: {"jie": "箪瓢陋巷，乐道忘贫。喻安贫守道、自得其乐，清名远播，福在平淡。", "diangu": "颜回一箪食一瓢饮，居陋巷而不改其乐，为孔子所赞。", "yunshi": "整体：安贫乐道，福在平淡。事业：守正自安，清誉自来。财运：清俭自足。感情：淡而有味。健康：心宽体健。"},
64: {"jie": "败师殿后，不矜其功。喻谦冲自牧、功成不居，反得众人敬重。", "diangu": "鲁国败退，孟之反殿后掩护，入城策马自谦，不夸己功。", "yunshi": "整体：谦者得福，功成不居。事业：谦逊自牧，众望所归。财运：稳步。感情：以德服人。健康：佳。"},
65: {"jie": "妖媚蔽君，国破身辱。喻沉迷声色、荒废正务则败，宜警醒自持。", "diangu": "陈后主宠张丽华，隋军破城，藏身胭脂井中终被擒，国破家亡。", "yunshi": "整体：警醒自持，勿耽逸乐。事业：防颓废败事。财运：有损。感情：防桃花劫。健康：节欲养身。"},
66: {"jie": "兰亭雅集，流觞赋诗，乐以忘忧。喻人缘极盛、文雅风流，诸事和乐。", "diangu": "王羲之会群贤于兰亭，曲水流觞，挥毫《兰亭序》，传为千古佳话。", "yunshi": "整体：人缘和乐，文雅风流。事业：众望所归，合作顺畅。财运：亨通。感情：良缘佳会。健康：畅和。"},
67: {"jie": "力拔山兮，终困乌江。喻恃勇则败，贵在保全身心，刚不可久，柔以自守。", "diangu": "项羽力能扛鼎、勇冠三军，然刚愎自用，终自刎乌江。", "yunshi": "整体：勿恃强好胜，保全为上。事业：勿恃强逞能。财运：防盛极而衰。感情：刚愎伤情。健康：防过劳。"},
68: {"jie": "久怀凌云，渭水钓时，终遇文王。喻怀才待聘、时来运转，明主将至，大展抱负。", "diangu": "姜子牙年迈垂钓渭水，周文王访贤车载而归，终辅周灭纣兴周。", "yunshi": "整体：时来运转，大展抱负。事业：得遇贵人，一展宏图。财运：渐入佳境。感情：良缘终成。健康：佳。"},
69: {"jie": "忠义存心，民安物阜。喻以诚感物、以德服人，难题自解，惠泽绵长。", "diangu": "韩愈贬潮州，作《祭鳄鱼文》投江，鳄患遂息，百姓安乐。", "yunshi": "整体：以德服人，难题自解。事业：德政有成，惠及他人。财运：渐旺。感情：以诚相待。健康：佳。"},
70: {"jie": "失马半途，祸福难料。喻得失无常、否泰相循，宜处之泰然，静观其变。", "diangu": "塞翁失马，人皆吊之，然马引良驹而归；其子折髀，反免于征役。", "yunshi": "整体：祸福相倚，泰然处之。事业：得失勿计，静观其变。财运：时好时坏，平常心。感情：顺其自然。健康：心态决定状态。"},
71: {"jie": "涸辙困鲋，待西江之水。喻急难当前、远水难救近火，宜自救互助，勿空等。", "diangu": "庄周见鲋鱼困于涸辙，求斗升之水，喻急人之难须及时。", "yunshi": "整体：急难当前，务实自救。事业：急需务实之举。财运：周转要紧。感情：患难相扶。健康：及早就医。"},
72: {"jie": "守株待兔，可笑可叹。喻固执守旧、不思进取则一事无成，宜求变通。", "diangu": "宋人偶得兔撞树而死，遂弃耕守株，终无所获，为天下笑。", "yunshi": "整体：勿守旧，求变通。事业：不可守株待兔。财运：忌坐等。感情：主动才有缘。健康：宜动不宜静。"},
73: {"jie": "蓝袍换锦，衣锦荣归。喻功成名就、光宗耀祖，大吉大利，所谋皆成。", "diangu": "状元及第，脱去蓝衫换锦袍，衣锦还乡，雁塔题名。", "yunshi": "整体：大吉大利，功成名就。事业：金榜题名，大展宏图。财运：极旺。感情：良缘美眷。健康：精神焕发。"},
74: {"jie": "运蹇妻离，覆水难收。喻贫贱之交不可弃，势利之心不可有，凡事以情义为先。", "diangu": "朱买臣贫时妻求去，后官拜太守，前妻欲复婚，泼水于地难收。", "yunshi": "整体：先抑后扬，守志为上。事业：守志笃行，终有出头。财运：前苦后甜。感情：覆水难收，悔之晚矣。健康：注意郁气。"},
75: {"jie": "婚姻岂厌家贫，势利终误己身。喻嫌贫爱富者自食其果，夫妻当同甘共苦。", "diangu": "伦文叙贫时夫妻离异，后中状元衣锦荣归，前妻悔恨坠楼。", "yunshi": "整体：同甘共苦，莫论贫富。事业：贫而志坚，终有出头。财运：先贫后富。感情：勿以贫富论缘。健康：戒嗔怒。"},
76: {"jie": "乐道修身，不义之财视如浮云。喻安贫乐道、守正不阿，心境澄明。", "diangu": "孔子赞颜回疏食饮水、曲肱而枕，乐在其中；不义富贵如浮云。", "yunshi": "整体：守正自安，淡泊明志。事业：守正自安，不慕虚名。财运：不贪则安。感情：平淡是真。健康：心宽体健。"},
77: {"jie": "虽陷缧绁，非己之殃，终得昭雪。喻一时蒙冤，问心无愧，清白自在。", "diangu": "公冶长通晓鸟语，被诬入狱，孔子知其贤，以女妻之，终白其冤。", "yunshi": "整体：蒙冤勿惧，真相自明。事业：一时蒙冤，守正自清。财运：有小波折。感情：误会可解。健康：无大碍。"},
78: {"jie": "春服既成，浴沂咏归。喻心境旷达、随缘自在，天时人和，诸事称心。", "diangu": "曾点言志：暮春浴于沂水，舞雩咏归，孔子喟然叹赏。", "yunshi": "整体：旷达自在，诸事称心。事业：从容自若，水到渠成。财运：顺遂。感情：和乐融融。健康：神清气爽。"},
79: {"jie": "富贵如春梦，何苦力争。喻看破荣华、急流勇退，知足者常乐。", "diangu": "张良辅汉功成，辞封万户侯，从赤松子游，明哲保身。", "yunshi": "整体：看破荣华，知足常乐。事业：功成宜退，随缘而安。财运：淡泊自守。感情：随缘。健康：清心寡欲。"},
80: {"jie": "弓影疑蛇，猜透即安。喻疑虑生暗鬼，明辨则泰来，凡事不必自扰。", "diangu": "乐广宴客，杯中有弓影如蛇，客疑而病，乐广解释后病愈。", "yunshi": "整体：疑虑尽释，否极泰来。事业：疑虑消解，转危为安。财运：转好。感情：猜忌是情之大忌。健康：疑病须释怀。"},
81: {"jie": "雌雉得时，上下飞鸣。喻时机合宜、进退自如，得其所哉。", "diangu": "孔子见山梁雌雉得其时，色举翔集，三嗅而作，叹其得时。", "yunshi": "整体：得时得位，进退自如。事业：把握时机，顺势而为。财运：顺。感情：称心如意。健康：佳。"},
82: {"jie": "击磬有心，知音荷蒉。喻怀才济世而道阻，宜安时守分，以待来者。", "diangu": "孔子击磬于卫，荷蒉者过门，闻磬声而知其有心济世。", "yunshi": "整体：志大时未至，守分待时。事业：韬光养晦，以待来者。财运：平平。感情：知音难觅。健康：郁结宜疏。"},
83: {"jie": "世事如山，富而忧贵，贪求无厌。喻人心不足蛇吞象，知足者安，莫作非分之想。", "diangu": "赤松子避世修仙，喻人当知足；反观世人既富犹忧，贪念不休。", "yunshi": "整体：知足常足，勿贪多求。事业：勿贪多务得。财运：知足则常足。感情：惜福惜缘。健康：戒欲养身。"},
84: {"jie": "满腹奇才，铁鸡难举，弃楚投汉。喻择木而栖、弃暗投明，自有出头之日。", "diangu": "韩信在楚不受重用，经张良指点弃楚投汉，终登坛拜将。", "yunshi": "整体：改换门庭，柳暗花明。事业：择良木而栖，弃暗投明。财运：渐佳。感情：另择良缘。健康：佳。"},
85: {"jie": "太乙燃藜，苦读终显。喻十年寒窗、一朝成名，功名富贵接踵而来。", "diangu": "刘向夜读，太乙真人燃藜杖照之，后官至光禄大夫，博学显达。", "yunshi": "整体：苦读成名，富贵自来。事业：学业功名大吉。财运：丰盈。感情：衣锦还乡，良缘遂心。健康：佳。"},
86: {"jie": "截发迎宾，贫而贤德。喻虽贫而礼数周全、母德流芳，家道必兴。", "diangu": "陶侃家贫，母湛氏截发易酒以款待宾客，范逵叹服，陶侃终成大器。", "yunshi": "整体：贤德之家，家道必兴。事业：以诚待人，自有回报。财运：由贫转兴。感情：家和万事兴。健康：安。"},
87: {"jie": "两雄相遇，各逞其才。喻旗鼓相当、互不服输，宜秉公持正，莫争闲气。", "diangu": "荀鸣鹤与陆士龙相会，各言所长，日下荀鹤、云间士龙传为佳话。", "yunshi": "整体：旗鼓相当，秉公持正。事业：竞争激烈，凭实力取胜。财运：平分秋色。感情：互敬为要。健康：平。"},
88: {"jie": "替父从军，巾帼须眉。喻孝义当头、敢作敢为，虽历艰难，终得嘉名。", "diangu": "花木兰女扮男装，替父从军十二载，忠孝两全，凯旋而归。", "yunshi": "整体：敢作敢为，终得嘉名。事业：敢闯敢拼，终成大器。财运：渐旺。感情：佳偶天成。健康：健朗。"},
89: {"jie": "挂剑酬心，人亡情在。喻重诺守信、物是人非，惟须防情义成空、时移世易。", "diangu": "季札出使徐国，心许宝剑；归来徐君已逝，乃挂剑墓树以践诺。", "yunshi": "整体：守信重诺，防时移世易。事业：守约可敬，防人走茶凉。财运：防失落。感情：缘尽犹念，徒增感伤。健康：伤怀。"},
90: {"jie": "夜奔识英雄，慧眼择良人。喻当机立断、自主姻缘，惟须慎察其人。", "diangu": "红拂女慧眼识李靖，夤夜私奔相随，后李靖建功立业。", "yunshi": "整体：慧眼识缘，当机立断。事业：果断则成。财运：有贵人相助。感情：慧眼识缘，大胆表白。健康：佳。"},
91: {"jie": "蟾宫桂香，玉镜团圆。喻蟾宫折桂、名利双全，团圆美满，大吉之象。", "diangu": "月宫桂树飘香，玉镜团圆高悬，喻中秋蟾宫折桂，功名圆满。", "yunshi": "整体：大吉之象，名利双全。事业：高中登科，前程似锦。财运：极旺。感情：团圆美满。健康：安和。"},
92: {"jie": "闻韶忘味，至乐入心。喻得遇至善、潜心向学，大道可成。", "diangu": "孔子周游至齐，闻《韶》乐，三月不知肉味，叹其尽美尽善。", "yunshi": "整体：潜心向学，大道可成。事业：专心致志，必有成就。财运：顺。感情：情投意合。健康：佳。"},
93: {"jie": "淫声败俗，国之将倾。喻近墨者黑，须远离诱惑，守正不移。", "diangu": "郑卫之音淫靡，孔子闻之不忍卒听，叹其乱雅乐、败风俗。", "yunshi": "整体：守正不移，远离诱惑。事业：防小人诱引。财运：防靡费。感情：防滥情。健康：戒声色。"},
94: {"jie": "一窟不容二虎，别岭各栖。喻两雄并立则争，宜各让一步、各得其所。", "diangu": "虬髯客见李靖英雄，知天下有主，乃让之一席，远走扶余自立。", "yunshi": "整体：各得其所，退让为安。事业：避免正面冲突。财运：各守各得。感情：合则留，不合则去。健康：平。"},
95: {"jie": "积土成山，由少而多。喻功在积累、持之以恒，莫畏辛劳，则大事可成。", "diangu": "女娲炼五色石补天，功在积篑成山，持之以恒乃成。", "yunshi": "整体：日积月累，终成其事。事业：持之以恒，莫畏辛劳。财运：聚少成多。感情：细水长流。健康：劳逸结合。"},
96: {"jie": "羌笛声悲，客子思归，孤雁传书。喻身在异乡、归心似箭，宜早定行止。", "diangu": "蔡文姬（文姬）流落异乡，闻笛思汉，南雁传书，归心难抑。", "yunshi": "整体：身在异乡，宜谋归计。事业：在外奔波，宜定行止。财运：平平。感情：两地相思。健康：思虑伤身。"},
97: {"jie": "小舟下饵，得鱼与否未可知。喻谋事结果难料，宜顺其自然，静观其变。", "diangu": "康顺倚楼观钓，一叶小舟频下饵，得鱼与否尚在未卜。", "yunshi": "整体：静观其变，顺其自然。事业：结果未明，静待分晓。财运：未可轻下注。感情：若即若离。健康：安。"},
98: {"jie": "种玉嫌狭，寻金厌多，贫富天定。喻人心不足，何苦奔波，知足惜福为要。", "diangu": "管仲与鲍叔牙分金，鲍叔知其家贫多与之，富贵不骄，义气千秋。", "yunshi": "整体：知足惜福，莫强求。事业：守成勿贪。财运：富贵有命，莫强求。感情：以义相交。健康：心静则安。"},
99: {"jie": "雪拥桥头，渔父莫开船。喻前路阻滞，宜暂缓行，坚守本心，勿偏勿躁。", "diangu": "韩愈遭贬，雪拥蓝关马不前；渔父亦因风狂不启航，宜守宜待。", "yunshi": "整体：前路受阻，缓进为佳。事业：行路艰难，静守待时。财运：暂守。感情：欲速不达。健康：防寒保暖。"},
100: {"jie": "百花贺春，否极泰来。喻穷极则变、苦尽甘来，万象更新，转祸为福。", "diangu": "唐明皇击鼓催花，百花竞放贺春，万物更新，喻否极泰来。", "yunshi": "整体：否极泰来，万象更新。事业：新局面开启，渐入佳境。财运：由贫转富。感情：苦尽甘来。健康：转好。"},
}
